          "ホームジム用プレハブは、床耐荷重・天井高・断熱性能の3点が最重要です。床耐荷重は最低でも1㎡あたり300kg以上、できれば500kg以上を選びましょう。パワーラック+ベンチ+ダンベルで200kg、使用者の体重と動作荷重を含めると局所的に400kg以上かかる場合があります。天井高は2.3m以上が理想で、懸垂動作やラックの設置に必要です。",
