          "多くの方が失敗するのは、最初から高頻度・高負荷のメニューを組んでしまうことです。週3回、1回30〜45分から始め、慣れてきたら徐々に強度を上げる方が長期的には効果的です。筋肉は休息中に成長するため、同じ部位は48〜72時間空けてトレーニングするのが基本です。"
