          "上級者向けのテクニックとして、ドロップセット・スーパーセット・レストポーズ法などがあります。ドロップセットは限界まで行った後すぐに重量を下げて続行する方法で、可変式ダンベルなら素早い重量変更が可能です。スーパーセットは拮抗筋を連続して鍛える方法で、例えば上腕二頭筋のカールと上腕三頭筋のエクステンションを休憩なしで行います。",
