    "title": "ハーフラックの選び方とホームジム活用法",
    "excerpt": "省スペースで本格的なバーベルトレーニングができるハーフラック。設置スペース、耐荷重、高さ調節機能を軸に、自宅に最適なモデルを選びましょう。",
