          "kind": "checklist",
          "brief": "設置面積60×60cm以下、天井高230cm以上、本体重量30kg以上の3項目をチェックリスト形式で表示。各項目に「確認必須」の印を付ける。",
          "imageUrl": "/blog/home-gym-compact-20260515-t5xob6/image-01.webp",
          "alt": "省スペース懸垂マシンの設置条件チェックリスト",
