          "また、省スペース型は設置面積が狭い分、前後方向の安定性が低くなります。体重70kg以上の場合、ベース部分にウェイトプレートを追加して重心を下げる対策が有効です。転倒リスクを避けるため、初回使用時は必ず安定性を確認してから本格的に使用してください。"
