          "brief": "ベンチ角度30度、45度、60度の3パターンで、大胸筋上部と三角筋前部の関与割合を図示。30度が大胸筋上部に最も効果的であることを視覚的に示す。",
          "imageUrl": "/blog/home-gym-dumbbell-20260513-ejqk43/image-01.webp",
          "alt": "インクラインベンチプレスの角度と筋肉への負荷の関係を示す図",
