          "また、床の耐荷重も重要な確認事項です。一般的な住宅の床は1㎡あたり180kg程度が目安とされますが、ラック・バーベル・プレート・自分の体重を合計すると200kgを超えることもあります。不安な場合は、重量を分散させる配置や、建物管理者への相談を検討してください。天井高も2.2m以上あると、プルアップバーなどの使用時に余裕が生まれます。"
