    "excerpt": "自宅にパワーラックを導入してホームジムを作る際の広さ、予算、床材、防音対策、安全性まで具体的に解説。初めての方でも失敗しない購入前の確認ポイントをまとめました。",
    "keyword": "パワーラックホームジム",
    "category": "rack",
